#!/usr/bin/env bash
# СУДИТ: дерево
# (предмет словами: строки *.sh дерева (hooks/, scripts/, lib/, bin/ и тесты); в строке СУДИТ — только пути, иначе прибор свидетелей-атак читает слова путями — D1222)
# probe_D1193 — формы `grep -c … || echo …` в дереве нет: `grep -c` при нуле совпадений САМ печатает 0 и выходит 1,
# запасной `echo` дописывает второй ноль, и подстановка даёт «0\n0» (корень D477: «совпадений ноль» и «файла нет» — одно
# значение). Образец замены — `k=$(grep -c … 2>/dev/null); echo "${k:-0}"`. Комментарии не считаются (форма описана в
# шапках прозой); строка с меткой `# grep-c-ok: <причина>` снята с учёта — форма бывает данными.
# Код: 0 — носителей нет; 1 — есть (названы); 2 — дерева нет.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
cd "$R" 2>/dev/null && git rev-parse --is-inside-work-tree >/dev/null 2>&1 || exit 2
# Образец собран так, чтобы не совпасть с самим собой: `[|][|]` вместо двух палок подряд. Ключи до `c` (`-vc`, `-E -c`),
# `--count`, одна `|` внутри шаблона и запасной `printf` — тот же дефект (скептик D1193, H1–H3). Перечень — и файлы до
# `git add`: новый носитель чаще рождается вместе со своим файлом (M1).
RE='grep([[:space:]]+-[[:alnum:]-]+)*[[:space:]]+(-[[:alpha:]]*c[[:alpha:]]*|--count)([^|]|[|][^|])*[|][|][[:space:]]*(echo|printf)'
hits=$(git ls-files -z --cached --others --exclude-standard -- '*.sh' | xargs -0 grep -nE "$RE" 2>/dev/null \
    | grep -vE '^[^:]+:[0-9]+:[[:space:]]*#' | grep -vE '# grep-c-ok: [^[:space:]]')
[ -z "$hits" ] && { echo "формы «grep -c с запасным echo» в дереве нет"; exit 0; }
printf '%s\n' "$hits" | cut -c1-160
echo "носителей: $(printf '%s\n' "$hits" | grep -c .) — замена: k=\$(grep -c … 2>/dev/null); echo \"\${k:-0}\""
exit 1
